use super::{Seeding, conflicts, pin_range, seed, seed_range, without_local_checksums};
use crate::lock::yarn_berry::{BerryLock, Descriptor};
use color_eyre::eyre;
use cooldown_core::CoreError;
use indoc::indoc;
use std::collections::HashSet;

/// The lock Yarn 4.18.1 wrote after a temporary exact pin of `chalk@4.1.1` in the root and
/// `packages/a`, whose `^4.0.0` it no longer records, beside `packages/b`'s `~4.1.0` and
/// `packages/c`'s exact `4.1.0`, both still bound to `chalk@4.1.0`.
const PINNED: &str = indoc! {r#"
    # This file is generated by running "yarn install" inside your project.
    # Manual changes might be lost - proceed with caution!

    __metadata:
      version: 10
      cacheKey: 10c0

    "a@workspace:packages/a":
      version: 0.0.0-use.local
      resolution: "a@workspace:packages/a"
      dependencies:
        chalk: "npm:4.1.1"
      languageName: unknown
      linkType: soft

    "b@workspace:packages/b":
      version: 0.0.0-use.local
      resolution: "b@workspace:packages/b"
      dependencies:
        chalk: "npm:~4.1.0"
      languageName: unknown
      linkType: soft

    "c@workspace:packages/c":
      version: 0.0.0-use.local
      resolution: "c@workspace:packages/c"
      dependencies:
        chalk: "npm:4.1.0"
      languageName: unknown
      linkType: soft

    "chalk@npm:4.1.0, chalk@npm:~4.1.0":
      version: 4.1.0
      resolution: "chalk@npm:4.1.0"
      dependencies:
        has-flag: "npm:^4.0.0"
      checksum: 10c0/3787bd65ec
      languageName: node
      linkType: hard

    "chalk@npm:4.1.1":
      version: 4.1.1
      resolution: "chalk@npm:4.1.1"
      dependencies:
        has-flag: "npm:^4.0.0"
      checksum: 10c0/3866c8b96e
      languageName: node
      linkType: hard

    "e7@workspace:.":
      version: 0.0.0-use.local
      resolution: "e7@workspace:."
      dependencies:
        chalk: "npm:4.1.1"
      languageName: unknown
      linkType: soft

    "has-flag@npm:^4.0.0":
      version: 4.0.0
      resolution: "has-flag@npm:4.0.0"
      languageName: node
      linkType: hard
"#};

/// The `chalk` ranges `ranges` as owned strings.
fn ranges(ranges: &[&str]) -> Vec<String> {
    ranges.iter().map(ToString::to_string).collect()
}

/// The `chalk@npm:<range>` descriptor.
fn chalk(range: &str) -> eyre::Result<Descriptor> {
    Descriptor::parse(&format!("chalk@{range}"))
        .ok_or_else(|| eyre::eyre!("chalk@{range} is no descriptor"))
}

/// The locator `lock` binds `descriptor` to, as Yarn spells it.
fn bound(lock: &BerryLock, descriptor: &Descriptor) -> Option<String> {
    lock.package_for(descriptor)
        .map(|package| package.locator.to_string())
}

/// A range no longer recorded is added to the pinned release's key and a range still bound to
/// the old copy is moved there, while the excluded exact pin keeps its own entry and every
/// other line stays as Yarn wrote it.
#[test]
fn seeding_binds_each_declared_range_to_the_pinned_release() -> eyre::Result<()> {
    let seeds = ranges(&["npm:^4.0.0", "npm:~4.1.0"]);
    let seeding = Seeding {
        name: "chalk",
        version: "4.1.1",
        ranges: &seeds,
    };

    let edited = seed(PINNED, &seeding)?;

    let lock = BerryLock::read(&edited)?;
    assert_eq!(
        bound(&lock, &chalk("npm:^4.0.0")?).as_deref(),
        Some("chalk@npm:4.1.1")
    );
    assert_eq!(
        bound(&lock, &chalk("npm:~4.1.0")?).as_deref(),
        Some("chalk@npm:4.1.1")
    );
    assert_eq!(
        bound(&lock, &chalk("npm:4.1.0")?).as_deref(),
        Some("chalk@npm:4.1.0")
    );
    // Only the two keys change: the old copy loses the moved range, the release gains both.
    let expected = PINNED
        .replace(
            "\"chalk@npm:4.1.0, chalk@npm:~4.1.0\":",
            "\"chalk@npm:4.1.0\":",
        )
        .replace(
            "\"chalk@npm:4.1.1\":",
            "\"chalk@npm:4.1.1, chalk@npm:^4.0.0, chalk@npm:~4.1.0\":",
        );
    assert_eq!(edited, expected);
    Ok(())
}

/// An entry whose every descriptor is seeded away is dropped with its fields and the blank line
/// after it, so the document still reads as a lock without that copy.
#[test]
fn an_entry_left_without_a_descriptor_is_dropped() -> eyre::Result<()> {
    let seeds = ranges(&["npm:4.1.0", "npm:~4.1.0"]);
    let seeding = Seeding {
        name: "chalk",
        version: "4.1.1",
        ranges: &seeds,
    };

    let edited = seed(PINNED, &seeding)?;

    assert!(
        !edited.contains("resolution: \"chalk@npm:4.1.0\""),
        "{edited}"
    );
    assert!(!edited.contains("\n\n\n"), "{edited}");
    let lock = BerryLock::read(&edited)?;
    assert_eq!(
        bound(&lock, &chalk("npm:4.1.0")?).as_deref(),
        Some("chalk@npm:4.1.1")
    );
    assert!(edited.contains("\"c@workspace:packages/c\":"), "{edited}");
    Ok(())
}

/// A key too long for a plain YAML key takes the explicit `? key` form, as Yarn writes it, and
/// an explicit key in the input is read and rewritten too.
#[test]
fn a_long_key_takes_the_explicit_form() -> eyre::Result<()> {
    let seeds: Vec<String> = (0..80)
        .map(|patch| format!("npm:^4.1.1 || ^0.0.{patch}"))
        .collect();
    let seeding = Seeding {
        name: "chalk",
        version: "4.1.1",
        ranges: &seeds,
    };

    let edited = seed(PINNED, &seeding)?;

    assert!(edited.contains("\n? \"chalk@npm:4.1.1, "), "{edited}");
    let lock = BerryLock::read(&edited)?;
    for range in &seeds {
        assert_eq!(
            bound(&lock, &chalk(range)?).as_deref(),
            Some("chalk@npm:4.1.1")
        );
    }

    // Seeding the edited lock once more moves one more range into the explicit key.
    let more = ranges(&["npm:~4.1.0"]);
    let again = seed(
        &edited,
        &Seeding {
            ranges: &more,
            ..seeding
        },
    )?;
    let lock = BerryLock::read(&again)?;
    assert_eq!(
        bound(&lock, &chalk("npm:~4.1.0")?).as_deref(),
        Some("chalk@npm:4.1.1")
    );
    assert_eq!(
        bound(&lock, &chalk("npm:^4.1.1 || ^0.0.0")?).as_deref(),
        Some("chalk@npm:4.1.1")
    );
    Ok(())
}

/// Seeding needs the release the temporary pin resolved: a pin the lock does not record, or one
/// resolved to anything but that registry release, is refused rather than guessed at.
#[test]
fn a_pin_without_its_release_is_refused() {
    let seeds = ranges(&["npm:^4.0.0"]);
    let missing = seed(
        PINNED,
        &Seeding {
            name: "chalk",
            version: "4.1.2",
            ranges: &seeds,
        },
    );
    assert!(
        matches!(&missing, Err(CoreError::LockUnreadable(message)) if message.contains("resolved no entry")),
        "{missing:?}"
    );

    let aliased = PINNED.replace(
        "resolution: \"chalk@npm:4.1.1\"",
        "resolution: \"has-flag@npm:4.1.1\"",
    );
    let foreign = seed(
        &aliased,
        &Seeding {
            name: "chalk",
            version: "4.1.1",
            ranges: &seeds,
        },
    );
    assert!(
        matches!(&foreign, Err(CoreError::LockUnreadable(message)) if message.contains("no registry release")),
        "{foreign:?}"
    );
}

/// A top-level line of a shape Yarn never writes stops the edit instead of being misread.
#[test]
fn an_unexpected_top_level_line_is_refused() {
    let seeds = ranges(&["npm:^4.0.0"]);
    let malformed = PINNED.replace("\"chalk@npm:4.1.1\":", "\"chalk@npm:4.1.1\": # pinned");
    let result = seed(
        &malformed,
        &Seeding {
            name: "chalk",
            version: "4.1.1",
            ranges: &seeds,
        },
    );
    assert!(
        matches!(&result, Err(CoreError::LockUnreadable(_))),
        "{result:?}"
    );
}

/// A range seeding may move is one the lock binds to the moved copy or the target, or does not
/// record; one bound to another copy, or one an excluded member records, is a conflict.
#[test]
fn conflicts_name_every_binding_the_landing_does_not_own() -> eyre::Result<()> {
    let excluded: HashSet<String> = HashSet::from(["packages/c".to_string()]);
    let check = |seeds: &[&str], from: &str| {
        let seeds = ranges(seeds);
        conflicts(
            PINNED,
            &Seeding {
                name: "chalk",
                version: "4.1.1",
                ranges: &seeds,
            },
            from,
            &excluded,
        )
    };

    // A range the lock does not record, and one bound to the moved copy
    assert_eq!(
        check(&["npm:^4.0.0", "npm:~4.1.0"], "4.1.0")?,
        Vec::<String>::new()
    );

    // A range bound to a copy the landing does not move
    let other = check(&["npm:~4.1.0"], "4.0.0")?;
    assert!(
        matches!(other.as_slice(), [reason] if reason.contains("also binds chalk@npm:4.1.0")),
        "{other:?}"
    );

    // A range an excluded member records
    let shared = check(&["npm:4.1.0"], "4.1.0")?;
    assert!(
        matches!(shared.as_slice(), [reason] if reason.contains("packages/c")),
        "{shared:?}"
    );
    Ok(())
}

/// Only a same-name registry range admitting the target seeds, spelled as the lock spells it.
#[test]
fn seed_ranges_are_registry_ranges_admitting_the_target() {
    assert_eq!(seed_range("^4.0.0", "4.1.1").as_deref(), Ok("npm:^4.0.0"));
    assert_eq!(
        seed_range("npm:~4.1.0", "4.1.1").as_deref(),
        Ok("npm:~4.1.0")
    );
    assert_eq!(seed_range("4.1.1", "4.1.1").as_deref(), Ok("npm:4.1.1"));
    assert_eq!(pin_range("4.1.1"), "npm:4.1.1");
    for (specifier, reason) in [
        ("^5.0.0", "does not admit 4.1.1"),
        ("latest", "no registry range"),
        ("npm:chalk@^4.0.0", "no registry range"),
        ("npm:other@^4.0.0", "no registry range"),
        ("file:./vendor/chalk", "no registry range"),
        ("patch:chalk@npm%3A4.1.1#./fix.patch", "no registry range"),
    ] {
        let refused = seed_range(specifier, "4.1.1");
        assert!(
            refused
                .as_ref()
                .is_err_and(|refusal| refusal.contains(reason)),
            "{specifier}: {refused:?}"
        );
    }
}

/// Only the checksum of a `file:` package goes, so Yarn packs it again into a fresh cache, while
/// every registry entry keeps its checksum and every descriptor its binding.
#[test]
fn local_checksums_are_dropped_and_nothing_else() -> eyre::Result<()> {
    let local = indoc! {r#"

        "local@file:./local::locator=e7%40workspace%3A.":
          version: 1.0.0
          resolution: "local@file:./local#./local::hash=7f2c1d&locator=e7%40workspace%3A."
          checksum: 10c0/a5b94c3623
          languageName: node
          linkType: hard
    "#};
    let lock = format!("{PINNED}{local}");

    let edited = without_local_checksums(&lock)?;

    assert_eq!(edited, lock.replace("  checksum: 10c0/a5b94c3623\n", ""));
    assert!(edited.contains("checksum: 10c0/3866c8b96e"));
    BerryLock::read(&edited)?;
    Ok(())
}
